NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Eine (die) Offenbarung Jesu Christi, die ihm Gott gegeben hat, [um] seinen Sklaven (Knechten, Dienern) das (die [Dinge], die) zu zeigen, was in Kürze (sehr bald) geschehen muss, und [die (was)] er erklärt (gezeigt) hat, indem er sie durch seinen Engel seinem Sklaven (Knecht, Diener) Johannes gesandt hat,',
        2: 'der Gottes Aussage (Wort) und das Zeugnis (Martyrium) Jesu Christi bezeugt hat – [alles], was er gesehen hat.',
        3: 'Wie glücklich [sind] derjenige, der die Worte dieser Prophetie verliest (vorliest), sowie (und) diejenigen, die sie hören und das darin (in ihr) Geschriebene beachten (befolgen, einhalten), denn der Zeitpunkt (die Zeit) [ist] nahe.',
        4: 'Johannes an die sieben Gemeinden in Asien: [Ich wünsche euch] Gnade und Frieden von Der Ist und Der War und Der Kommen Wird, und von den sieben Geistern, die vor seinem Thron [sind],',
        5: 'und von Jesus Christus, der treue Zeuge, der Erstgeborene (Erste) der Toten und der Herrscher [über] die Könige der Erde. Dem, der uns liebt, und uns von unseren Sünden erlöst hat mit (durch; in) seinem Blut –',
        6: 'und er hat uns [zu] einem Königreich gemacht, [zu] Priestern [vor] Gott, seinem Vater – ihm [gebührt] die Herrlichkeit und die Herrschaft bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter), amen.',
        7: 'Schau, er kommt mit den Wolken, und es wird ihn jedes Auge sehen, auch (und) diejenigen, die ihn durchbohrt haben, und es werden alle Völker (Stämme) der Erde ihn beklagen. Ja, amen.',
        8: 'Ich bin das Alpha und das Omega, sagt JHWH (Herr), der Gott, Der Ist (Seiende) und Der War (Gewesene) und Der Kommen Wird (Kommende), der Allmächtige (Zebaot).',
        9: 'Ich, Johannes, euer Bruder und Teilhaber am Leiden (Not, Schwierigkeiten, Trübsal) und der Königsherrschaft (Reich, Königreich) und Ausdauer (Geduld, Ausharren) in Jesus, befand mich auf der Insel, die Patmos genannt wird, wegen (aufgrund) des Wortes Gottes und des Zeugnisses (der Bezeugung) Jesu.',
        10: 'Ich befand mich im Geist am Tag des Herrn und ich hörte hinter mir eine Stimme, laut wie eine Trompete (laute Stimme wie eine Trompete),',
        11: 'die sprach (rief, sagte): „Was du siehst, schreibe in ein Buch und sende den sieben Gemeinden, nach Ephesus, {und} nach Smyrna, {und} nach Pergamon, {und} nach Thyatira, {und} nach Sardis, {und} nach Philadelphia und nach Laodizäa!“',
        12: 'Und ich wandte (drehte) mich um, [um] die Stimme zu sehen, die mit mir sprach, und als (indem) ich mich umwandte (umdrehte), sah ich sieben goldene Lampenständer (Leuchter),',
        13: 'und in der Mitte der Lampenständer (Leuchter) einen ähnlich [den] Sohn eines Menschen (Menschensohn). Er trug (der trug; war gekleidet in) einen langen Mantel und hatte einen goldenen Gürtel um seine Brust geschnallt.',
        14: 'Sein Kopf und seine Haare {aber} [waren] weiß wie weiße Wolle, wie Schnee, und seine Augen [sahen aus (waren)] wie eine Feuerflamme,',
        15: 'und seine Füße [waren] polierter Bronze ähnlich, wie im Ofen gebrannt, und seine Stimme [klang] wie das Geräusch (die Stimme) vieler Gewässer,',
        16: 'und er hielt in seiner rechten Hand sieben Sterne, und aus seinem Mund kam ein zweischneidiges, scharfes Schwert heraus, und sein Gesicht scheint wie die Sonne in ihrer Kraft.',
        17: 'Und als ich ihn sah, fiel ich vor (auf) seine Füße wie tot – und er legte seine Rechte auf mich und sagte: „Fürchte dich nicht! Ich bin der Erste und der Letzte,',
        18: 'und der Lebende – und ich wurde tot und schau, ich bin lebendig bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter) - und ich habe die Schlüssel [zu] Tod und Hades.',
        19: 'Schreibe daher (nun) [die Dinge] auf, die du gesehen hast: (gesehen hast und) die sind und die noch (später, danach) stattfinden (geschehen) werden.',
        20: 'Das Geheimnis der sieben Sterne, die du in (über) meiner Rechten gesehen hast, und die sieben goldenen Lampenständer (Leuchter): Die sieben Sterne sind Engel (Boten) der sieben Gemeinden, und die sieben Lampenständer (Leuchter) sind die sieben Gemeinden. “',
    },
    2: {
        1: 'Dem Engel der Kirche (Gemeinde) in Ephesus schreibe: Dieses sagt der, der die sieben Sterne in seiner Rechten festhält, der inmitten der sieben goldenen Leuchtern umhergeht:',
        2: 'Ich kenne deine Werke und deine Mühe und deine Ausdauer, und [ich weiß,] dass du Böse nicht erträgtst, und diejenigen (die) geprüft hast, die sich Apostel nennen und [es] nicht sind, und sie (als) Lügner gefunden (erkannt) hast,',
        3: 'und Ausdauer hast und ertragen (gelitten) hast wegen meines Namens und nicht müde geworden bist.',
        4: 'Aber ich habe gegen dich, dass du deine Liebe, die erste, verlassen hast.',
        5: 'Erinnere dich also, von wo aus du gefallen bist und kehre um (ändere deinen Sinn, bekehre dich, bereue) und verwirkliche (tu) die ersten Werke. Wenn aber nicht, komme ich zu dir und entferne deinen Leuchter von (aus) seinem Platz, wenn du nicht umkehrst (nicht deinen Sinn änderst, dich nicht bekehrst, bereust).',
        6: 'Aber dies hast du, dass du die Werke der Nikolaiter (der Anhänger des Nikolaos) hasst, die auch ich hasse.',
        7: 'Wer ein Ohr hat, höre, was der Geist den Kirchen (Gemeinden) sagt. Dem, der siegt, werde ich zu essen geben vom (aus dem) Holz (Baum) des Lebens, das im Garten (Paradies) Gottes ist.',
        8: 'Und dem Engel der Kirche (Gemeinde) in Smyrna schreibe: Dies sagt der Erste und der Letzte, der tot war und zum Leben kam:',
        9: 'Ich kenne deine Bedrängnis (Not; deinen Kummer) und deine Armut – aber du bist reich – und die Verleumdung (Lästerung) von Seiten derer (aus denen), die behaupten (sich sagen) Juden zu sein und [es] nicht sind, sondern eine Versammlung (Synagoge) des Satans.',
        10: 'In keiner Weise fürchte das, was (die Dinge, die) du im Begriff bist zu leiden (du leiden wirst; sollst). Sieh, der Teufel (Verleumder) ist im Begriff, [einige] von (aus) euch ins Gefängnis zu werfen, damit ihr versucht (erprobt, geprüft) werdet und ihr werdet zehn Tage lang Bedrängnis (Not, Kummer) haben. Sei treu bis zum Tod, und ich werde dir den Kranz (die Krone) des Lebens geben.',
        11: 'Wer ein Ohr hat, höre, was der Geist den Kirchen (Gemeinden) sagt. Wer siegt, soll in keiner Weise Schaden (Unrecht) leiden aus dem zweiten Tod.',
        12: 'Und dem Engel der Kirche (Gemeinde) in Pergamon schreibe: Dies sagt der, der das Schwert, das zweischneidige, das scharfe hat:',
        13: 'Ich weiß, wo du wohnst, wo der Thron des Satans [ist], und du hältst meinen Namen fest und du hast meinen Glauben nicht verleugnet (verweigert), sogar (auch) in den Tagen des Antipas, mein Zeuge, mein treuer, der getötet wurde bei euch, wo der Satan wohnt.',
        14: 'Aber ich habe gegen dich wenig (wenige Dinge), weil du dort [solche (einige)] hast, die (sich an) die Lehre des Balaam festhalten (halten), der dem Balak gelehrt hat, einen Anstoß (eine Verführung, ein Ärgernis) vor die Söhne Israels zu werfen (die Söhne Israels zu verführen), den Götzen Geopfertes (Götzenopferfleisch) zu essen und Unzucht zu treiben.',
        15: 'So hast auch du [solche (einige)], die (sich an) die Lehre der Nikolaiter gleicherweise festhalten (halten).',
        16: 'Kehr um (Ändere deinen Sinn, Bekehre dich, Bereue) also: Wenn aber nicht, komme ich zu dir schnell und führe Krieg gegen sie (mit ihnen) mit dem Schwert meines Mundes.',
        17: 'Wer ein Ohr hat, höre, was der Geist den Kirchen (Gemeinden) sagt. Dem, der siegt, werde ich {ihm} vom Manna, dem verborgenen geben und ich werde ihm einen weißen Stein (Kiesel) geben, und auf dem Stein (Kiesel) einen neuen Namen geschrieben, den keiner kennt, außer dem, der [ihn] empfängt.',
        18: 'Und dem Engel der Kirche (Gemeinde) in Thyatira schreibe: Dies sagt der Sohn Gottes, der {seine} Augen hat wie eine Flamme von Feuer und {seine} Füße gleich glänzender Bronze.',
        19: 'Ich kenne deine Werke und deine Liebe und [deine] Gerechtigkeit und [deine] Ausdauer, und deine letzten Werke [, die] mehr [sind] als die ersten.',
        20: 'Aber ich habe gegen dich, dass du die Frau Isebel duldest (zulässt, lässt), die von sich behauptet, Prophetin zu sein (die sich Prophetin sagt/nennt) und lehrt und meine Knechte in die Irre führt, Unzucht zu treiben und den Götzen Geopfertes (Götzenopferfleisch) zu essen.',
        21: 'Und ich habe ihr Zeit gegeben, damit sie umkehre (ihren Sinn ändere, sich bekehre, bereue), und sie will nicht umkehren (nicht ihren Sinn änderen, sich nicht bekehren, nicht bereuen) von (aus) ihrer Unzucht.',
        22: 'Sieh, ich werfe sie auf die (in die) Bahre (Liege) und diejenigen, die mit ihr Ehebruch begehen in eine große Bedrängnis, wenn sie nicht umkehren (nicht ihren Sinn ändern, sich nicht bekehren, nicht bereuen) von (aus) ihren Werken,',
        23: 'und ihre Kinder werde ich töten in einem Tod. Und alle die Kirchen (Gemeinden) werden wissen, dass ich der bin, der Nieren und Herzen erforscht, und ich werde euch – einem jeden (jedem) – entsprechend eurer Werke geben.',
        24: 'Euch aber sage ich, den übrigen in Thyatira, alle die diese Lehre nicht haben, welche die Tiefen Satans nicht erkannt haben, wie sie sagen: Nicht werfe ich auf euch eine andere Last,',
        25: 'jedoch (nur), was ihr habt, haltet fest, bis ich komme.',
        26: 'Und wer siegt und bis zum Ende meine Werke bewahrt, dem (ihm) werde ich Vollmacht über die Völker geben',
        27: 'und er wird sie mit einem eisernen Stab weiden, {so} wie die tönernen Gefäße zerschlagen werden,',
        28: 'wie auch ich von meinem Vater empfangen habe, und ich werde ihm den Morgenstern geben.',
        29: 'Wer ein Ohr hat, höre, was der Geist den Kirchen (Gemeinden) sagt.',
    },
    3: {
        7: 'Und dem Geist (Engel, Beschützer, Wächter) der Gemeinde in Philadelphia schreibe: „Dies sagt der Heilige, der Wahrhaftige (Wahre), der den Schüssel Davids hat, der öffnet und niemand wird schließen und der schließt und niemand öffnet.',
        8: 'Ich kenne deine Taten (Betätigungen, Werke, Leistungen). Schau (siehe), ich habe vor dir eine geöffnete Tür (eingesetzt),die niemand schließen kann. Denn du hast eine kleine Kraft und hast mein Wort bewahrt (bewacht) und hast meinen Namen nicht verleugnet.',
        9: 'Schau (siehe) ich gebe (bestimme) welche aus der Synagoge des Satans, die sich selber Juden nennen und sie sind es nicht, sondern sie lügen. Schau (siehe), ich werde bewirken (machen), dass sie kommen werden und sich vor deinen Füßen niederwerfen (niederkniend beten) und sie werden erkennen, dass ich dich geliebt habe.',
        10: 'Weil du auf das Wort geachtet hast, geduldig auf mich zu warten, werde auch ich dich halten in der Stunde der Prüfung (Verlockung, Versuchung, Anfechtung), die über den ganzen Erdkreis kommen wird,um die Bewohner auf der ganzen Erde zu prüfen (versuchen, verlocken).',
        11: 'Ich komme bald (schnell, eilig): Halte (halte fest, ergreife), was du hast, damit niemand deinen Siegeskranz (Preis, Lohn, Zierde) nimmt.',
        12: 'Wer siegt, den werde ich zu einer Säule im Tempel meines Gottes machen und er wird nie mehr herausgehen. Weiter werde ich auf ihn den Namen meines Gottes schreiben und den Namen der Stadt meines Gottes, des neuen Jerusalems, das aus dem Himmel von meinem Gott herabkommt und meinen neuen Namen.“',
        13: 'Wer ein Ohr hat, höre, was der Geist den Gemeinden sagt!',
    },
    4: {
        1: 'Danach sah ich {und schau} eine offen stehende Tür im Himmel, und die Stimme – die erste, die ich wie eine Posaune mit mir sprechen gehört hatte – sprach: „Komm herauf, dann (und) werde ich dir zeigen, was danach geschehen muss!“',
        2: 'Plötzlich (sofort) befand ich mich im Geist – und schau, ein Thron stand im Himmel, und auf dem Thron saß jemand,',
        3: 'und der [da] saß, [war] [in seinem] Aussehen (Erscheinungsbild) [dem] Edelstein (Stein) Jaspis (Jaspisstein) und Sarder (Karneol) ähnlich, und ein Regenbogen [war] rings um den Thron, [in seinem] Aussehen (Erscheinungsbild) Smaragden ähnlich.',
        4: 'Und rings um den Thron [standen] 24 Throne, und auf den Thronen saßen 24 Älteste (Greise), gekleidet in weiße Gewänder (Kleidung), und auf ihren Köpfen [hatten sie] goldene Siegeskränze.',
        5: 'Und aus den Thronen kamen Lichtstrahlen (Blitze), {und} Geräusche (Stimmen) und Donner. Und sieben Lampen [mit] Feuer brannten vor dem Thron, das sind die sieben Geister Gottes,',
        6: 'und vor dem Thron [befand sich etwas (eine Fläche?)] wie ein gläsernes Meer, Kristall ähnlich. Und inmitten des Thrones und rings um den Thron [standen] vier Lebewesen voller Augen vorne und hinten',
        7: 'und das erste Lebewesen [war] einem Löwen ähnlich, {und} das zweite Lebewesen [war] einem Jungstier ähnlich, {und} das dritte Lebewesen hatte ein Gesicht wie ein Mensch, {und} das vierte Lebewesen [war] einem fliegenden Adler ähnlich.',
        8: 'Und die vier Lebewesen (Gestalten, Tiere, Geschöpfe), eines wie das andere {von ihnen} je sechs Flügel habend, sind außen (außen herum) und innen voller Augen. Und sie rufen Tag und Nacht ohne Unterbrechung: „Heilig, heilig, heilig [ist] der Herr (JHWH), Gott, der Allmächtige (Zebaot), Der War (Gewesene) und Der Ist (Seiende) und Der Kommen Wird (Kommende)!“',
        9: 'Und immer wenn die Lebewesen dem auf dem Thron Sitzenden Herrlichkeit und Ehre und Dank geben (geben werden), der lebt bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter),',
        10: 'werfen sich (werden sich niederwerfen) die 24 Ältesten (Greise) vor dem auf dem Thron Sitzenden nieder und beten den an, der bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter) lebt, und sie werfen ihre Siegeskränze vor den Thron, wobei (während) sie rufen:',
        11: '„Würdig bist du, unser Herr und Gott, die Herrlichkeit und die Ehre und die Macht zu empfangen (zu ergreifen, anzunehmen, zu nehmen), denn du hast alles (alle [Dinge]) erschaffen, und durch deinen Willen waren (existierten) sie und wurden sie erschaffen!“',
    },
    5: {
        1: 'Und ich sah auf (in) der rechten [Hand] des auf dem Thron Sitzenden eine Schriftrolle (ein Dokument, Buch), auf der Innen- und der Rückseite (innen und außen) beschrieben, [mit] sieben Siegeln versiegelt.',
        2: 'Und ich sah, wie (dass) ein starker (mächtiger) Engel mit lauter Stimme verkündete: „Wer [ist] würdig, die Schriftrolle (das Dokument, Buch) zu öffnen und ihre Siegel aufzubrechen?“',
        3: 'Und niemand, weder im Himmel noch auf der Erde noch unter der Erde, war in der Lage (vermochte), die Schriftrolle (das Dokument, Buch) zu öffnen oder hineinzusehen (sie anzusehen/zu sehen).',
        4: 'Und ich begann heftig zu weinen (weinte heftig), weil niemand für würdig befunden wurde, die Schriftrolle (das Dokument, Buch) zu öffnen oder hineinzusehen (sie anzusehen/zu sehen).',
        5: 'Und einer von den Ältesten (Greisen) sagte zu mir: „Weine nicht! Schau, der Löwe aus dem Stamm Juda, die Wurzel Davids hat gesiegt, [um nun] die Schriftrolle (das Dokument, Buch) und ihre sieben Siegel zu öffnen!“',
        6: 'Und ich sah, dass (wie) in der Mitte des Thrones und der vier Lebewesen und in der Mitte der Ältesten (Greise) ein Lamm (Schaf) stand [und aussah], als sei es (wie) geschlachtet (ermordet). Es hatte sieben Hörner und sieben Augen – das sind die sieben Geister Gottes, ausgesandt in die ganze Welt.',
        7: 'Und es kam (ging) und nahm [die Schriftrolle (das Dokument, Buch)] aus der rechten [Hand] dessen, der auf dem Thron saß.',
        8: 'Und als er die Schriftrolle (das Dokument, Buch) empfing (nahm, in Empfang nahm, erhielt, in die Hand nahm), fielen die vier Lebewesen und die 24 Ältesten (Greise) vor dem Lamm (Schaf) nieder, wobei jeder [von ihnen] eine Zither (Harfe, Lyra) und goldene Schüsseln (Schalen) voller Weihrauch hielt (hatte) – das sind die Gebete der Heiligen –,',
        9: 'und sie sangen ein neues Lied {mit dem Text}: „Würdig bist du, die Schriftrolle (das Dokument, Buch) zu empfangen (zu nehmen, in Empfang zu nehmen, erhalten) und ihre Siegel zu öffnen, denn (weil) du wurdest geschlachtet (ermordet) und hast [für] Gott mit (durch, mithilfe, anhand) deinem Blut [Menschen] (uns) aus jedem Stamm, {und} [jeder] Sprache, {und} [jedem] Volk und [jeder] Nation (Volk) erworben (losgekauft, ausgelöst)',
        10: 'und sie [für] unseren Gott [zu] einem Königreich und [zu] Priestern gemacht, und sie werden als Könige über die (auf der) Erde herrschen (regieren; Könige sein)!“',
        11: 'Und ich sah, und hörte [die] Stimmen (den Klang) vieler Engel um den Thron herum und der Lebewesen und der Ältesten (Greise), und ihre Anzahl betrug (war) zehntausend mal zehntausend und tausend mal tausend,',
        12: 'die mit lauter Stimme riefen (sagten): „Würdig ist das Lamm (Schaf), das geschlachtet wurde, die Macht, und den Reichtum, {und} Weisheit, {und} Kraft, {und} Ehre, {und} Herrlichkeit und Lob zu empfangen!“',
        13: 'Und die ganze Schöpfung, {die} im Himmel, {und} auf der Erde und unter der Erde und im (auf dem) Meer und alles, was in ihnen ist, hörte ich rufen (sagen): „Dem, der auf dem Thron sitzt und dem Lamm (Schaf) [gebührt] das Lob und die Ehre, {und} die Herrlichkeit und die Herrschaft bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter)!“',
        14: 'Und die vier Lebewesen riefen (antworteten, sagten): „Amen!“und die Ältesten fielen nieder und beteten an.',
    },
    7: {
        1: 'Danach sah ich vier Engel, die auf den vier Ecken der Erde standen [und] die vier Winde der Erde festhielten (kontrollierten), weil (mit dem Ziel, dass; damit) kein Wind gegen (auf) die Erde oder gegen (auf) das Meer oder gegen (auf) irgendeinen Baum wehen sollte.',
        2: 'Und ich sah einen anderen Engel, der vom Aufgang der Sonne (der aufgehenden Sonne) her heraufstieg [und] den Siegelstempel (Petschaft, Siegel) des Lebendigen Gottes dabei hatte, und er rief [mit] lauter Stimme den vier Engeln zu, denen [die Gewalt (Fähigkeit, Macht)] {ihnen} gegeben war, der Erde und dem Meer Schaden zuzufügen,',
        3: '{und sagte}: „Fügt weder der Erde noch dem Meer noch den Bäumen Schaden zu, bis wir die Sklaven unseres Gottes auf ihren Stirnen gekennzeichnet (versiegelt, markiert) haben!“',
        4: 'Und ich hörte die Anzahl der Gekennzeichneten (Versiegelten, Markierten), 144 000, gekennzeichnet (versiegelt, markiert) aus jedem Stamm der Kinder Israels (Söhne Israels; Israeliten):',
        5: 'Aus [dem] Stamm Juda 12 000 Gekennzeichnete (Versiegelte, Markierte), aus [dem] Stamm Ruben 12 000, aus [dem] Stamm Gad 12 000,',
        6: 'aus [dem] Stamm Ascher 12 000, aus [dem] Stamm Naftali 12 000, aus [dem] Stamm Manasse 12 000,',
        7: 'aus [dem] Stamm Simeon 12 000, aus [dem] Stamm Levi 12 000, aus [dem] Stamm Issachar 12 000,',
        8: 'aus [dem] Stamm Sebulon 12 000, aus [dem] Stamm Josef 12 000, aus [dem] Stamm Benjamin 12 000 Gekennzeichnete (Versiegelte, Markierte).',
        9: 'Nach diesen [Ereignissen] sah ich {und siehe} eine große Menschenmasse, die niemand {sie} zählen konnte, aus jeder Nation (Volk) und [allen] Stämmen, {und} Völkern und Sprachen vor dem Thron und vor dem Lamm (Schaf) stehen. Sie waren in weiße Gewänder gekleidet und [trugen] Palmenzweige in ihren Händen.',
        10: 'Und sie riefen (rufen) [mit] lauter Stimme {und sagten (sagen) }: „Die Rettung [verdanken wir?] unserem Gott, der auf dem Thron sitzt, und dem Lamm (Schaf)!“',
        11: 'Und alle Engel standen rings um den Thron und die Ältesten (Greise) und die vier Lebewesen und fielen vor dem Thron auf ihre Gesichter und beteten Gott an',
        12: '{und sagten}: „Amen (Ja), das Lob und die Herrlichkeit und die Weisheit und die Dankbarkeit (Dank) und die Ehre und die Macht und die Kraft [gebühren (gehören)] unserem Gott bis in die Ewigkeiten (Zeitalter) der Ewigkeiten (Zeitalter), amen!“',
        13: 'Und einer von den Ältesten (Greisen) wandte sich an mich und fragte: „Diejenigen, die in die weißen Gewänder (Kleider) gekleidet sind – wer sind sie und woher sind sie gekommen?“',
        14: 'und ich sagte zu ihm: „Mein Herr, du weißt [es].“Und er sagte zu mir: „Es sind diejenigen, die aus der größten (großen) Bedrängnis gekommen sind, und sie haben ihre Gewänder (Kleider) gewaschen und sie mit dem (im) Blut des Lammes (Schafs) weiß gemacht (geweißt).',
        15: 'Aus diesem Grund (Deshalb) sind sie vor dem Thron Gottes und dienen (verehren) ihm Tag und Nacht in seinem Tempel, und der auf dem Thron Sitzende wird über (bei) ihnen wohnen (sein Zelt aufschlagen).',
        16: 'Sie werden nicht mehr hungern und nicht mehr dürsten, und weder die Sonne noch irgendeine Hitze werden auf sie niederdrücken,',
        17: 'weil das Lamm (Schaf) in der Mitte des Thrones ihr Hirte ist (sie weidet) und sie zu Quellen frischen Wassers führt, und Gott wird jede Träne von ihren Augen abwischen.“',
    },
    12: {
        1: 'Und es erschien ein großes Zeichen am Himmel (im Himmel): eine Frau, umworfen mit der Sonne, und der Mond unter ihren Füssen, und auf ihrem Haupt ein Kranz von zwölf Sternen.',
        2: 'Sie trägt schwanger, und sie schreit in Wehen und Schmerzen einer Geburt.',
        3: 'Und ein anderes Zeichen erschien am Himmel: Siehe, ein Drache, gross und feuerrot, mit sieben Köpfen und zehn Hörnern, und auf seinen Köpfen sieben Diademe.',
    },
    13: {
        1: 'Und ich sah ein Tier aus dem Meer aufsteigen, welches zehn Hörner und sieben Köpfe und auf seinen Hörnern zehn Diademe und auf seinen Köpfen einen blasphemischen Namen hatte.',
        2: 'Und das Tier, welches ich sah, war wie ein Leopard und seine Füße wie die eines Bären und sein Mund wie der Mund eines Löwen. Und der Drache gab ihm seine Macht und seinen Thron und große Gewalt.',
        3: 'Und [ich sah] einen seiner Köpfe wie zu Tode ge-schlachtet und die Wunde seines Todes wurde geheilt. Und die ganze Welt wunderte sich hinter dem Tier her.',
        4: 'Und sie beteten den Drachen an,weil er dem Tier die Gewalt gegeben hatte, und sie beugten ihre Knie vor dem Tier, wobei sie sagten: „Wer ist wie das Tier und wer kann es bekämpfen?“',
        5: 'Und ihm wurde ein Mund gegeben um Lautes und Blasphemisches zu reden und ihm wurde Gewalt gegeben, (es) zweiundvierzig Monate zu tun',
        6: 'Und es öffnete seinen Mund zur Blasphemie um Gott zu lästern, seinen Namen und sein Zelt und diejenigen, welche im Himmel leben.',
        7: 'ihm wurde gegeben die Gewalt über jeden Stamm und (jedes) Volk und (jede) Sprache und (jede) Nation.',
        8: 'Und alle, die auf der Erde leben, werden vor ihm ihre Knie beugen, (jeder) dessen Name nicht geschrieben wurde in das Buch des Lebens des geschlachteten Lammes, vom Anfang der Welt an.',
        9: 'Wenn jemand ein Ohr hat, so höre er.',
        10: 'Wenn jemand in Gefangenschaft führt, so geht er in Gefangenschaft Wenn jemand mit einem Schwert tötet, so wird er mit einem Schwert getötet. Hier ist die Geduld und der Glaube der Heiligen.',
        11: 'Und ich sah ein anderes Tier aus der Erde hinaufsteigen und es hatte zwei Hörner wie ein Lamm und sprach wie ein Drache.',
        12: 'Und die ganze Gewalt des ersten Tieres tat es vor ihm, und es veranlasst die Erde und die auf ihr Lebenden, dass sie das erste Tier anbeten, dessen tödliche Wunde geheilt wurde.',
        13: 'Und es tut große Zeichen, indem es auch selbst Feuer aus dem Himmel auf die Erde herabkommen lasse vor den Menschen.',
        14: 'Und es täuschte diejenigen, welche auf der Erde wohnen, durch die Zeichen, die ihm vor dem Tier zu tun gegeben worden, indem es diesen auf der Erde Lebenden befahl, dem Tier ein Bild zu machen, welches die Wunde des Schwertes hat und (wieder) lebendig wurde.',
        15: 'Und ihm wurde gegeben dem Bild des Tieres Geist zu geben, sodass auch das Bild des Tieres sprach und veranlasste, dass alle getötet werden, die nicht anbeten das Bild des Tieres.',
        16: 'Und es veranlasst alle dazu, die Kleinen und die Großen, und die Reichen und die Armen, und die Freien und die Sklaven, dass sie sich ein Malzeichen geben an die rechte Hand oder ihre Stirn.',
        17: 'und so dass niemand kaufen oder verkaufen kann, wenn nicht derjenige, der das Zeichen des Namens des Tieres hat oder die Zahl seines Namens.',
        18: 'Da ist Erkenntnis vonnöten: Wer den Geist (Fähigkeit) hat, errechne die Nummer des Tieres - die Nummer für einen Menschen -: Seine Nummer ist sechshundertsechsundsechzig.',
    },
}
